// Chat.js
import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';

const Chat = () => {
  const location = useLocation();
  const { personality, botName } = location.state || {};  // '/settings'에서 전달된 값

  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [error, setError] = useState(null);

  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    // 사용자의 메시지 추가
    const newMessage = { sender: "user", message: userInput };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);

    // 입력창 비우기
    setUserInput("");

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ user_input: userInput, personality, bot_name: botName }),  // bot_name 전달
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "오류가 발생했습니다.");
      }

      const data = await response.json();
      const chatbotMessage = data.response;

      // 챗봇 응답 추가
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "chatbot", message: `${botName}: ${chatbotMessage}` },  // 응답에 챗봇 이름 추가
      ]);
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError(error.message);
    }
  };

  // 엔터 키를 눌렀을 때 메시지를 전송하도록 처리
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSendMessage();
    }
  };

  return (
    <div>
      <div>
        {chatHistory.map((chat, index) => (
          <div key={index} className={chat.sender}>
            <strong>{chat.sender === "user" ? "User" : botName}:</strong> {chat.message}
          </div>
        ))}
      </div>
      <div>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={handleKeyDown}  // 엔터 키 입력 감지
        />
        <button onClick={handleSendMessage}>전송</button>
      </div>
    </div>
  );
};

export default Chat;
